<?php
declare(strict_types=1);
require_once __DIR__ . '/../../api/config/admin-authorization.php';
narrrfs_require_admin_request('owner_control.lab_store_drafts.ui.v1');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner Control — Lab Store Drafts</title><style>
body{font-family:system-ui;background:#111820;color:#f4f7fb;padding:24px}main{max-width:1100px;margin:auto}.grid{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}.card,form,section,details{background:#1b2530;border:1px solid #33404c;border-radius:12px;padding:16px;margin:14px 0}label{display:block;margin:8px 0}input,textarea,button,select{width:100%;box-sizing:border-box;padding:9px}button{margin-top:10px}.muted{color:#b8c6d2}.notice{min-height:1.5em}.source-result{display:flex;gap:8px;align-items:center;justify-content:space-between;border-top:1px solid #33404c;padding:10px;cursor:pointer}.source-result:focus{outline:2px solid #8d61ff}.source-result button{width:auto;margin:0}.preview{max-width:160px;max-height:120px;display:block;margin-top:8px}.hidden{display:none}.selected-source{border-color:#8d61ff}.selected-actions{display:flex;gap:8px}.selected-actions button{width:auto}.advanced summary{cursor:pointer;font-weight:600}
</style></head><body><main>
<a href="/owner-control/v1/index.php">← Owner Control</a><h1>Lab Store Draft Workspace</h1><p class="muted">Planning workspace only. Saving does not publish an offer or change a catalog, balance, inventory, or purchase.</p><p id="status" class="notice" role="status">Loading…</p>
<label>Filter drafts <input id="draft_filter" placeholder="Filter loaded drafts"></label><section id="list" class="grid"></section>
<section><h2>Choose an existing item</h2><p class="muted">Optional, read-only catalog search. Choose an item to attach it to this draft.</p><label>Catalog <select id="source_search_type"><option value="normal_store">Normal Store items</option><option value="genetic_item">Genetic Items</option></select></label><label>Find an item <input id="source_query" maxlength="80" placeholder="Search by name"></label><div class="selected-actions"><button type="button" id="source_search">Find items</button><button type="button" id="source_browse">Browse items</button></div><div id="source_results"></div></section>
<section id="selected_source_card" class="selected-source hidden" aria-live="polite"><h2>Selected source</h2><p id="selected_source">No item selected.</p><img id="source_preview" class="preview hidden" alt="Selected item preview"><div class="selected-actions"><button type="button" id="change_source">Change</button><button type="button" id="clear_source">Clear</button></div></section>
<form id="form"><input id="draft_id" type="hidden"><input id="expected_version" type="hidden"><h2 id="form_heading">Create draft</h2><p id="draft_state" class="muted">Private draft — not live offer</p><section><h3>Basic item details</h3><label>Title <input id="title" required></label><label>Category <input id="category" required></label><label>Description <textarea id="description" required></textarea></label><label>Image <input id="media_upload" type="file" accept="image/png,image/jpeg,image/webp"></label><button type="button" id="upload_media">Upload selected image</button><p class="muted">The image is attached to this private draft only after Save draft.</p><label>Planned League Points price <input id="proposed_lp_price" type="number" min="0"></label><label>Planned DSPOINC price <input id="proposed_dspoinc_price" type="number" min="0"></label><label>Planned stock <input id="proposed_stock" type="number" min="0"></label></section><details class="advanced"><summary>Advanced draft metadata</summary><p class="muted">Optional planning references only. These do not change an existing item or image.</p><label>Selected catalog type <select id="proposed_source_type"><option value="">No catalog item selected</option><option value="normal_store">Normal Store item</option><option value="genetic_item">Genetic Item</option></select></label><label>Selected catalog ID <input id="proposed_source_item_id" type="number" min="1"></label><label>Manual image or preview reference <input id="media_reference"></label></details><button>Save draft</button></form>
</main><script>
'use strict';
const ids=['title','category','description','media_reference','proposed_source_type','proposed_source_item_id','proposed_lp_price','proposed_dspoinc_price','proposed_stock'],list=document.getElementById('list'),status=document.getElementById('status'),form=document.getElementById('form'),draftFilter=document.getElementById('draft_filter'),sourceResults=document.getElementById('source_results'),sourcePreview=document.getElementById('source_preview'),selectedSource=document.getElementById('selected_source'),selectedCard=document.getElementById('selected_source_card'),draftState=document.getElementById('draft_state');let pending=null,loadedDrafts=[],sourceBrowse={type:'',query:'',nextCursor:null,seen:new Set()};
function val(id){return document.getElementById(id).value}function set(id,v){document.getElementById(id).value=v??''}function payload(){const p={title:val('title'),category:val('category'),description:val('description'),media_reference:val('media_reference')||null,proposed_source_type:val('proposed_source_type')||null,proposed_source_item_id:val('proposed_source_item_id')?Number(val('proposed_source_item_id')):null,proposed_lp_price:val('proposed_lp_price')?Number(val('proposed_lp_price')):null,proposed_dspoinc_price:val('proposed_dspoinc_price')?Number(val('proposed_dspoinc_price')):null,proposed_stock:val('proposed_stock')?Number(val('proposed_stock')):null};if(val('draft_id')){p.draft_id=Number(val('draft_id'));p.expected_version=Number(val('expected_version'))}return p}function fingerprint(p){return JSON.stringify(p)}function keyFor(p){const f=fingerprint(p);if(!pending||pending.fingerprint!==f)pending={fingerprint:f,key:crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','')};return pending.key}
function safePreview(ref){sourcePreview.classList.add('hidden');sourcePreview.removeAttribute('src');if(!ref)return;sourcePreview.src=ref;sourcePreview.onerror=()=>{sourcePreview.classList.add('hidden');selectedSource.textContent+=' Preview unavailable.'};sourcePreview.classList.remove('hidden')}
function renderSelectedCard(item){selectedCard.classList.remove('hidden');selectedSource.textContent='Private draft — not live offer · '+item.title+' · '+item.source_type+' · '+item.source_state;safePreview(item.presentation_ref)}
function clearSelection(){set('proposed_source_type','');set('proposed_source_item_id','');selectedCard.classList.add('hidden');safePreview(null);pending=null}
function selectSource(item){set('proposed_source_type',item.source_type);set('proposed_source_item_id',item.source_item_id);if(!val('title').trim())set('title',item.title);if(item.presentation_ref&&!val('media_reference').trim())set('media_reference',item.presentation_ref);renderSelectedCard(item);pending=null;status.textContent='Item selected for this draft.'}
function show(d){ids.forEach(k=>set(k,d[k]));set('draft_id',d.draft_id);set('expected_version',d.version);document.getElementById('form_heading').textContent='Edit draft';draftState.textContent=d.state==='draft'?'Private draft — not live offer':'Draft state unavailable';pending=null;if(d.proposed_source_type&&d.proposed_source_item_id)renderSelectedCard({title:d.proposed_source_type+' #'+d.proposed_source_item_id,source_type:d.proposed_source_type,source_state:'saved',presentation_ref:d.media_reference});else clearSelection()}
async function openDraft(id){const r=await fetch('/api/owner-control/v1/lab-store/draft-details.php?draft_id='+encodeURIComponent(id),{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p.success)throw Error();show(p.draft);status.textContent='Draft loaded for editing.'}
function renderDrafts(){const q=draftFilter.value.trim().toLowerCase();list.replaceChildren();loadedDrafts.filter(d=>!q||[d.title,d.category,d.proposed_source_type].join(' ').toLowerCase().includes(q)).forEach(d=>{const c=document.createElement('article');c.className='card';const h=document.createElement('strong');h.textContent=d.title+' — draft';const state=document.createElement('p');state.textContent=d.state==='draft'?'Private draft — not live offer':'Draft state unavailable';const m=document.createElement('p');m.textContent=d.proposed_source_type?'Selected catalog item: '+d.proposed_source_type:'No catalog item selected';const b=document.createElement('button');b.type='button';b.textContent='Open / Edit';b.onclick=()=>openDraft(d.draft_id).catch(()=>status.textContent='Details unavailable.');c.append(h,state,m,b);list.append(c)});if(!list.childElementCount)list.textContent='No matching drafts.'}
async function load(){const r=await fetch('/api/owner-control/v1/lab-store/drafts.php',{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p.success)throw Error();loadedDrafts=p.drafts;renderDrafts();status.textContent=p.drafts.length?'Drafts loaded.':'No drafts yet.'}
function appendSources(p,append){sourceResults.querySelectorAll('[data-show-more]').forEach(button=>button.remove());p.items.forEach(item=>{const key=item.source_type+':'+item.source_item_id;if(sourceBrowse.seen.has(key))return;sourceBrowse.seen.add(key);const row=document.createElement('div'),label=document.createElement('span'),choose=document.createElement('button');row.className='source-result';row.tabIndex=0;row.setAttribute('role','button');label.textContent=item.title+' · '+item.source_state;choose.type='button';choose.textContent='Use this item';choose.onclick=e=>{e.stopPropagation();selectSource(item)};row.onclick=()=>selectSource(item);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectSource(item)}};row.append(label,choose);sourceResults.append(row)});sourceBrowse.nextCursor=typeof p.page.next_cursor==='string'?p.page.next_cursor:null;if(sourceBrowse.nextCursor!==null){const more=document.createElement('button');more.type='button';more.dataset.showMore='true';more.textContent='Show more';more.onclick=()=>loadSources(sourceBrowse.query,sourceBrowse.nextCursor,true).catch(()=>status.textContent='Catalog search unavailable.');sourceResults.append(more)}if(!sourceResults.childElementCount)sourceResults.textContent='No matching catalog items found.'}
async function loadSources(query='',cursor=null,append=false){const type=val('source_search_type');if(!append||sourceBrowse.type!==type||sourceBrowse.query!==query){append=false;sourceBrowse={type,query,nextCursor:null,seen:new Set()};sourceResults.replaceChildren()}const params=new URLSearchParams({type,limit:'20'});if(query)params.set('q',query);if(cursor!==null)params.set('cursor',cursor);const r=await fetch('/api/owner-control/v1/lab-store/draft-sources.php?'+params,{credentials:'same-origin',cache:'no-store'}),p=await r.json();if(!r.ok||!p.success)throw Error();appendSources(p,append)}
async function searchSources(){const q=val('source_query').trim();if(q.length<2){status.textContent='Enter at least two characters to search, or use Browse items.';return}await loadSources(q)}
async function uploadMedia(){const file=document.getElementById('media_upload').files[0];if(!file){status.textContent='Choose an image first.';return}status.textContent='Uploading image…';try{const cr=await fetch('/api/owner-control/v1/lab-store/draft-csrf.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'upload_media'})}),ct=await cr.json();if(!cr.ok||!ct.success)throw Error();const body=new FormData();body.append('image',file);const r=await fetch('/api/owner-control/v1/lab-store/draft-media-upload.php',{method:'POST',headers:{'X-CSRF-Token':ct.csrf_token},body,credentials:'same-origin'}),out=await r.json();if(!r.ok||!out.success||typeof out.media_reference!=='string')throw Error();set('media_reference',out.media_reference);safePreview(out.media_reference);pending=null;status.textContent='Image ready. Save draft to attach it to this private draft.'}catch{status.textContent='Image upload failed. Manual image reference remains available.'}}
document.getElementById('source_search').onclick=()=>searchSources().catch(()=>status.textContent='Catalog search unavailable.');document.getElementById('source_browse').onclick=()=>loadSources().catch(()=>status.textContent='Catalog browse unavailable.');document.getElementById('upload_media').onclick=uploadMedia;document.getElementById('change_source').onclick=()=>document.getElementById('source_query').focus();document.getElementById('clear_source').onclick=clearSelection;draftFilter.addEventListener('input',renderDrafts);ids.forEach(id=>document.getElementById(id).addEventListener('input',()=>{if(pending&&pending.fingerprint!==fingerprint(payload()))pending=null}));
form.onsubmit=async e=>{e.preventDefault();const p=payload(),editing=Boolean(p.draft_id);p.idempotency_key=keyFor(p);status.textContent='Saving draft…';try{const a=editing?'update':'create',cr=await fetch('/api/owner-control/v1/lab-store/draft-csrf.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:a})}),ct=await cr.json(),r=await fetch(editing?'/api/owner-control/v1/lab-store/draft-update.php':'/api/owner-control/v1/lab-store/draft-create.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':ct.csrf_token},body:JSON.stringify(p)}),out=await r.json();if(r.status===409&&out.error==='version_conflict')throw Error('version_conflict');if(!r.ok||!out.success)throw Error();pending=null;status.textContent='Draft saved.';await load()}catch(x){status.textContent=x.message==='version_conflict'?'Version conflict: reload the draft before saving.':'Draft save failed; retry unchanged data to reuse its idempotency key.'}};load().catch(()=>status.textContent='Drafts unavailable.');
</script></body></html>
